  }
  try {
    await scrubCache(request);
  } catch (error) {
    throw new ErasureStepError('cache_cleanup_failed', error);
  }
  try {
    await scrubSearchIndex(request);
  } catch (error) {
    throw new ErasureStepError('search_cleanup_failed', error);
  }
}
