action.new_str:
async complete(event: EventEnvelope, customerId: string | undefined, partition: number, offset: number): Promise<void> {
  await transaction(async (client) => {
    // The erasure check runs under the shared advisory lock so a concurrent erasure scrub
    // either removes this row or prevents it from carrying personal data at all.
    const scrub = customerId !== undefined
      ? (await advisoryLock(client, erasureLockKey(event.merchantId, customerId)),
         await isCustomerErasureRequested(event.merchantId, customerId, client))
      : false;
    await client.query(
      `INSERT INTO operations.analytics_events
       (merchant_id,customer_id,anonymous_id,event_type,email,properties,occurred_at,source_event_id)
       VALUES($1,$2,$3,$4,$5,$6,$7,$8)
       ON CONFLICT(source_event_id) WHERE source_event_id IS NOT NULL DO NOTHING`,
      [
        event.merchantId,
        customerId ?? null,
        `anon_${event.aggregateId}`,
        event.eventType,
        scrub ? null : event.payload.email ?? event.payload.customerEmail ?? null,
        scrub ? {} : event.payload,
        event.occurredAt,
        event.eventId,
      ],
    );

