async function complete(job: ClaimedJob<ReceiptJob>): Promise<void> {
  // Receipts are retained financial records; for an erased customer the receipt is still
  // generated, but its customer block can never carry personal data again.
  const payload = await isCustomerErasureRequested(job.payload.merchantId, job.payload.customerId)
    ? { ...job.payload, customerSnapshot: { erased: true } }
    : job.payload;
  const stored = await storeReceipt(payload);

