import { executeErasure } from '../apps/privacy-worker/src/executor.js';
import { pool } from '../packages/database/src/pool.js';

const requestId = process.argv[2]!;
const result = await pool.query(`SELECT * FROM customers.erasure_requests WHERE id=$1`, [requestId]);
const request = result.rows[0];
if (!request) throw new Error('request not found');
try {
  await executeErasure(request as never);
  console.log('SUCCESS');
} catch (error) {
  console.error('FAILED:', error);
  if (error instanceof Error && error.cause) console.error('CAUSE:', error.cause);
} finally {
  await pool.end();
}

