import { Redis } from 'ioredis';
import { config } from '../packages/config/src/index.js';
import { CUSTOMER_INDEX, searchClient } from '../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../packages/storage/src/minio.js';

const merchant = '10000000-0000-4000-8000-000000000001';
const keys: string[] = [];
await new Promise<void>((resolve, reject) => {
  const stream = objectStore.listObjectsV2(DOCUMENT_BUCKET, `${merchant}/`, true);
  stream.on('data', (item: { name?: string }) => { if (item.name) keys.push(item.name); });
  stream.on('error', reject);
  stream.on('end', resolve);
});
console.log('== MinIO objects ==');
for (const key of keys.sort()) {
  const stream = await objectStore.getObject(DOCUMENT_BUCKET, key);
  const chunks: Buffer[] = [];
  for await (const chunk of stream as AsyncIterable<Buffer | string>) chunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk);
  const body = Buffer.concat(chunks).toString('utf8');
  const hasPii = /ada\.lovelace|Ada Lovelace|415-555-0101|crm-ada-001/.test(body);
  console.log(key, hasPii ? '*** CONTAINS PII ***' : 'clean', key.includes('receipts/ca2908d2') || key.includes('invoices/0627a725') ? ` => ${body.slice(0, 220)}` : '');
}

const redis = new Redis(config().REDIS_URL);
console.log('== Redis ==');
let cursor = '0';
do {
  const [next, found] = await redis.scan(cursor, 'MATCH', `merchant:${merchant}:customer:*`, 'COUNT', 100);
  cursor = next;
  for (const key of found) {
    const type = key.endsWith(':activity') ? 'hash' : 'string';
    const value = type === 'hash' ? JSON.stringify(await redis.hgetall(key)) : await redis.get(key);
    console.log(key, '=>', value?.slice(0, 200));
  }
} while (cursor !== '0');
await redis.quit();

console.log('== OpenSearch ==');
const result = await searchClient.search({ index: CUSTOMER_INDEX, body: { query: { match_all: {} }, size: 10 } });
for (const hit of result.body.hits.hits as Array<{ _id: string; _source: unknown }>) {
  console.log(hit._id, JSON.stringify(hit._source).slice(0, 200));
}

